use crate::Context;

/// The profile a file is held to.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Held {
    /// The 26-bit profile, ARMv4: the ARM7TDMI's ARM state less `BX`.
    Bit26,
    /// The 32-bit profile, ARMv7: Thumb, and ARM state's `BX`.
    Bit32,
}

impl Held {
    const fn profile(self) -> &'static Profile {
        match self {
            Self::Bit26 => &BIT26,
            Self::Bit32 => &BIT32,
        }
    }

    /// The sample this profile's vectors are written to.
    const fn sample(self) -> &'static str {
        match self {
            Self::Bit26 => "arm7tdmi-26bit.bin",
            Self::Bit32 => "arm7tdmi-32bit.bin",
        }
    }
}

const BOTH: [Held; 2] = [Held::Bit26, Held::Bit32];

